insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_11_v1'
from (values
('128.35.c.1.A',3,'A listener shows respect during a partner''s talk by:','["keeping eye contact and waiting to respond", "checking messages", "whispering to a neighbor", "finishing sentences for the speaker"]'::jsonb,0,'Active listening means attending and responding at the right time.','original'),
('128.35.c.1.A',3,'A learner replies to a classmate: ''That is a good point, and I would add one example.'' This reply is:','["a way to end the talk", "appropriate and builds on the speaker", "rude and off topic", "silent and unrelated"]'::jsonb,1,'It acknowledges the speaker and contributes.','original'),
('128.35.c.1.B',2,'Before a lab on magnets, a learner tells the group how magnets work in a toy at home. The learner is:','["taking attendance", "citing a source", "sharing prior knowledge", "revising a draft"]'::jsonb,2,'Prior knowledge helps the group communicate.','original'),
('128.35.c.1.B',2,'Why does a team gain from each member''s earlier experiences?','["Nobody needs to listen", "Talking becomes shorter", "The topic changes", "Ideas and examples from many backgrounds make talk clearer"]'::jsonb,3,'Shared experience supports communication.','original'),
('128.35.c.1.C',3,'A teacher says: ''Fold the paper, label each half, then write two facts.'' To follow this, the learner should:','["complete the actions in the same order", "wait for a classmate to finish", "do the actions in any order", "do only the last action"]'::jsonb,0,'Multi-step directions are followed in sequence.','original'),
('128.35.c.1.C',3,'To confirm multi-step directions, a learner can:','["wait silently", "repeat them back in his or her own words", "skip to the end", "copy a neighbor without listening"]'::jsonb,1,'Restating checks understanding.','original'),
('128.35.c.1.D',3,'A formal presentation should open with:','["a long apology", "an unrelated joke", "a clear thesis that previews the main point", "a list of page numbers"]'::jsonb,2,'A thesis gives the talk a focus.','original'),
('128.35.c.1.D',3,'Ideas in a formal talk should be arranged:','["in random order", "by length of word", "from last to first only", "in a logical progression"]'::jsonb,3,'Logical order helps listeners follow.','original'),
('128.35.c.1.E',3,'A group member adds a fact that connects to a partner''s idea. The member is:','["building on the ideas of others", "ending the discussion", "working alone", "changing the topic"]'::jsonb,0,'Collaboration builds on contributions.','original'),
('128.35.c.1.E',3,'In a team task, a learner contributes relevant information by:','["repeating the same point", "offering facts that fit the assignment", "waiting for others to finish", "telling stories from a different topic"]'::jsonb,1,'Relevant contributions move the group forward.','original'),
('128.35.c.1.F',2,'Asking a store clerk for help finding an item is an example of:','["a literary analysis", "a technical manual", "social communication in a real situation", "a research report"]'::jsonb,2,'Social language serves everyday purposes.','original'),
('128.35.c.1.F',2,'Which situation calls for purposeful oral language?','["Staring at a wall", "Humming alone", "Folding paper quietly", "Explaining a problem to a counselor"]'::jsonb,3,'Purposeful speech has a goal and an audience.','original'),
('128.35.c.1.G',3,'After a presentation, a peer says: ''Your visuals were clear, but speak more slowly.'' This comment is:','["critique to listen to and respond to", "an insult to ignore", "a new topic", "a grade"]'::jsonb,0,'Peer critique helps a speaker improve.','original'),
('128.35.c.1.G',3,'A good reply to peer critique is:','["pretending not to hear", "thanking the peer and considering the suggestion", "leaving the room", "arguing every point"]'::jsonb,1,'A respectful response invites growth.','original'),
('128.35.c.10.A',3,'A poster urges families to recycle. Its message is most likely meant to:','["explain a poem''s rhyme", "tell a bedtime story", "persuade readers to change behavior", "record a family tree"]'::jsonb,2,'A call to action is persuasive.','original'),
('128.35.c.10.A',3,'A science article full of formulas and unexplained terms is probably written for:','["very young children", "people who dislike reading", "no audience at all", "readers with background in the subject"]'::jsonb,3,'Technical content signals an informed audience.','original'),
('128.35.c.10.B',3,'An author lists problems first and then offers fixes. The text structure is:','["problem and solution", "chronological order", "description only", "sequence of steps"]'::jsonb,0,'The text moves from difficulty to answer.','original'),
('128.35.c.10.B',3,'Which structure best helps an author show how two cities are alike and different?','["chronological order", "compare and contrast", "problem and solution", "cause and effect"]'::jsonb,1,'Compare and contrast shows similarities and differences.','original'),
('128.35.c.10.C',3,'Why might an author add a map to a history chapter?','["to fill empty space", "to hide the facts", "to show locations the text describes", "to replace the index"]'::jsonb,2,'Graphic features support the purpose.','original'),
('128.35.c.10.C',3,'Italic and bold words in a textbook usually signal:','["errors", "page numbers", "the author''s age", "key terms or emphasis"]'::jsonb,3,'Print features draw attention to important words.','original'),
('128.35.c.10.D',3,'The phrase ''a river of cars'' shapes the reader''s view by suggesting traffic that is:','["endless and flowing", "tiny and slow", "wet and cold", "silent and empty"]'::jsonb,0,'Figurative language shapes perception.','original'),
('128.35.c.10.D',3,'An author describes a storm as ''angry''. This word choice makes the storm seem:','["small and quiet", "alive and threatening", "harmless and dull", "dry and distant"]'::jsonb,1,'Personification affects how readers see the storm.','original'),
('128.35.c.10.E',4,'A character says ''Great weather!'' while soaked in a downpour. This is:','["motif", "simile", "sarcasm", "alliteration"]'::jsonb,2,'Sarcasm says the opposite of what is meant.','original'),
('128.35.c.10.E',4,'A color, object or image that returns throughout a story is a:','["caption", "glossary", "citation", "motif"]'::jsonb,3,'A motif is a repeated element that supports meaning.','original'),
('128.35.c.10.F',4,'Short, choppy sentences with harsh words often create a mood of:','["tension", "amusement", "sleepiness", "relaxation"]'::jsonb,0,'Syntax and diction shape mood.','original'),
('128.35.c.10.F',4,'A writer''s tone is the:','["type of paper", "attitude toward the subject", "length of the text", "number of chapters"]'::jsonb,1,'Tone is the author''s attitude.','original'),
('128.35.c.10.G',4,'''Easy to start, hard to finish'' uses antithesis because it:','["asks a question", "repeats one word three times", "sets opposite ideas side by side", "lists steps in order"]'::jsonb,2,'Antithesis contrasts opposing ideas.','original'),
('128.35.c.10.G',4,'''We will work, we will learn, we will succeed'' uses parallelism by:','["adding a footnote", "using opposite ideas", "hiding the verb", "repeating the same grammatical pattern"]'::jsonb,3,'Parallelism repeats structure for emphasis.','original'),
('128.35.c.11.A',3,'Which prewriting tool helps a learner sort ideas before drafting?','["a graphic organizer", "a spelling test", "a bibliography only", "a final copy"]'::jsonb,0,'Organizers help plan ideas.','original'),
('128.35.c.11.A',3,'A writer who asks ''Who will read this and why?'' is planning for:','["font and margins", "audience and purpose", "grading and recess", "staples and folders"]'::jsonb,1,'Planning considers readers and goals.','original'),
('128.35.c.11.B.i',3,'For a story about an event, which structure fits best?','["reverse alphabet", "alphabetical order", "chronological order", "random order"]'::jsonb,2,'Events are told in time order.','original'),
('128.35.c.11.B.i',3,'A cause-and-effect essay is best organized by:','["listing unrelated facts", "using only quotations", "ordering paragraphs by length", "linking each cause to its results"]'::jsonb,3,'Structure should fit the purpose.','original'),
('128.35.c.11.B.ii',3,'Which sentence adds depth to the idea ''Pollution harms rivers''?','["Fertilizer runoff in 2019 killed thousands of fish in one Texas river.", "Rivers are wet.", "Pollution is bad.", "Many people live near water."]'::jsonb,0,'Specific details and examples develop an idea.','original'),
('128.35.c.11.B.ii',3,'Specific details make a paragraph engaging because they:','["hide the topic", "help readers picture and trust the idea", "replace the thesis", "shorten the paper"]'::jsonb,1,'Details bring ideas to life.','original'),
('128.35.c.11.C',3,'Revising for style means changing:','["only the paper size", "only staples", "how sentences sound and flow", "only the date"]'::jsonb,2,'Style concerns the sound and flow of writing.','original'),
('128.35.c.11.C',3,'A learner reads a draft aloud and finds a confusing paragraph. The next step is to:','["change the font only", "submit it as is", "delete the title", "revise it for clarity"]'::jsonb,3,'Revision improves clarity.','original'),
('128.35.c.11.D.i',3,'Which fixes the fragment ''Because the test was hard''?','["Because the test was hard, many students studied twice.", "Because the test was hard.", "Hard because the test.", "Test hard because."]'::jsonb,0,'A fragment needs a main clause to be complete.','original'),
('128.35.c.11.D.ii',3,'Which verb keeps the tense consistent? ''Yesterday she opened the door and ___ inside.''','["will walk", "walked", "is walking", "walks"]'::jsonb,1,'Both actions are in the past.','original'),
('128.35.c.11.D.iii',3,'Choose the correct verb: ''The books on the shelf ___ new.''','["am", "be", "are", "is"]'::jsonb,2,'The plural subject books takes are.','original'),
('128.35.c.11.D.iv',3,'Which pronoun fits? ''Every student must bring ___ own pencil.''','["your", "our", "its", "his or her"]'::jsonb,3,'Every student is singular, so the pronoun matches.','original'),
('128.35.c.11.D.iv',3,'Choose the correct pronoun: ''The coach praised Dana and ___.''','["me", "mine", "myself", "I"]'::jsonb,0,'The pronoun is an object of praised.','original'),
('128.35.c.11.D.ix',3,'Which is the standard abbreviation for ''Avenue''?','["Avn.", "Ave.", "Av", "Aven"]'::jsonb,1,'Ave. is standard in addresses.','original'),
('128.35.c.11.D.v',3,'Which phrase shows plural possession?','["the girl''s team", "the girls team''", "the girls'' team", "the girls''s team"]'::jsonb,2,'A plural noun ending in s takes only an apostrophe.','original'),
('128.35.c.11.D.v',3,'Which phrase uses an apostrophe to show possession?','["dogs'' are barking", "the dogs bone''s", "two dog''s", "the dog''s bone"]'::jsonb,3,'Singular possessives add ''s.','original'),
('128.35.c.11.D.vi',3,'Choose the correct word: ''The students put ___ books away.''','["their", "there", "thare", "they''re"]'::jsonb,0,'Their shows possession.','original'),
('128.35.c.11.D.vi',3,'Choose the correct word: ''I will ___ a letter to my aunt.''','["wright", "write", "right", "rite"]'::jsonb,1,'Write means to put words on paper.','original'),
('128.35.c.11.D.vii',3,'Which word must be capitalized?','["window", "happy", "Thursday", "carefully"]'::jsonb,2,'Days of the week are capitalized.','original'),
('128.35.c.11.D.vii',3,'Which of these is capitalized in a sentence?','["a season", "a color", "the word table", "the name of a country"]'::jsonb,3,'Proper nouns such as country names are capitalized.','original'),
('128.35.c.11.E',3,'Which sentence combines ''The boy was tired. The boy went home.'' best?','["The tired boy went home.", "Went home the boy tired.", "The boy tired went home.", "The boy, tired, home."]'::jsonb,0,'Combining removes repetition.','original'),
('128.35.c.11.E',3,'Joining ''I met a girl. She plays chess.'' with ''who'' gives:','["I met who a girl plays chess.", "I met a girl who plays chess.", "Who I met a girl plays chess.", "I met a girl, who she plays chess."]'::jsonb,1,'A relative clause combines the sentences.','original'),
('128.35.c.11.F',3,'Which sentence shows more personal voice?','["Kitchens are rooms.", "The kitchen was in a house.", "I still remember the smell of my grandmother''s kitchen.", "A kitchen has a stove."]'::jsonb,2,'Voice comes through specific, personal detail.','original'),
('128.35.c.11.F',3,'Voice in a writer''s work is most affected by:','["ink color", "page margins", "paper weight", "word choice and sentence rhythm"]'::jsonb,3,'Diction and rhythm create voice.','original'),
('128.35.c.11.G',2,'Which is a way to publish writing for a real audience?','["submitting it to a school magazine", "erasing it", "putting it in a drawer", "leaving a draft unfinished"]'::jsonb,0,'Publishing shares polished work with readers.','original'),
('128.35.c.12.A',3,'Which element is typical of a short story?','["a table of data", "plot with conflict and resolution", "a glossary", "a bibliography"]'::jsonb,1,'Fiction uses plot elements.','original'),
('128.35.c.12.A',3,'A poet creates imagery by:','["listing sources", "adding footnotes", "using sensory details", "drawing a chart"]'::jsonb,2,'Sensory language forms images.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_11_v1'
from (values
('128.35.c.12.B',3,'A report on volcanoes should mostly contain:','["invented events", "jokes about rock", "only opinions", "accurate facts and clear explanations"]'::jsonb,3,'Informational texts inform with facts.','original'),
('128.35.c.12.B',3,'Which is a personal essay topic?','["What learning a new language taught me about patience", "The boiling point of water", "Instructions for a stapler", "A list of state capitals"]'::jsonb,0,'Personal essays reflect on experience.','original'),
('128.35.c.12.C',3,'A strong argument includes a counterargument because it:','["removes the claim", "shows the writer has considered other views", "lengthens the title", "avoids evidence"]'::jsonb,1,'Addressing opposing views strengthens an argument.','original'),
('128.35.c.12.C',3,'Which is the best evidence for the claim ''Homework should be shorter''?','["Homework is a word", "Some teachers wear glasses", "A survey showing students sleep less when homework is long", "Students go to school"]'::jsonb,2,'Evidence must directly support the claim.','original'),
('128.35.c.12.D',3,'Which closing is appropriate for a business letter?','["XOXO", "Later!", "See ya!", "Sincerely,"]'::jsonb,3,'Business letters use formal closings.','original'),
('128.35.c.12.D',3,'A friendly letter to a cousin may include:','["personal news and a casual tone", "a formal subject line", "legal citations", "technical jargon"]'::jsonb,0,'Friendly letters are informal and personal.','original'),
('128.35.c.13.A',3,'Which is an open-ended research question?','["Do hurricanes exist?", "How do hurricanes affect coastal communities?", "Are hurricanes named?", "Is a hurricane wind?"]'::jsonb,1,'Open questions invite investigation.','original'),
('128.35.c.13.A',3,'An informal inquiry might be:','["a final bibliography", "a published thesis", "wondering aloud why the sky is red at sunset", "a formal debate"]'::jsonb,2,'Informal inquiry is casual curiosity.','original'),
('128.35.c.13.B',3,'Midway through research, a student finds the plan is not working. Critiquing the process means:','["ending the project", "restarting without thinking", "hiding the weak source", "identifying the problem and adjusting the next step"]'::jsonb,3,'Critique leads to changes.','original'),
('128.35.c.13.B',3,'Noticing that a search returned unrelated results leads a researcher to:','["try different keywords", "use the same words", "copy any result", "quit the topic"]'::jsonb,0,'Adjusting the search improves results.','original'),
('128.35.c.13.C',3,'A research plan usually lists:','["only a title", "steps, sources to try and a timeline", "only a joke", "only a signature"]'::jsonb,1,'A plan organizes the work.','original'),
('128.35.c.13.C',3,'Revising a plan after finding a new area of interest means:','["ignoring new sources", "deleting the question", "updating steps to match the new direction", "keeping the old steps"]'::jsonb,2,'Plans change as inquiry develops.','original'),
('128.35.c.13.D',3,'A student''s question ''What happened in the Civil War?'' is too broad. A narrowed version is:','["What is war?", "What happened in history?", "Who fought?", "How did railroads affect Union supply?"]'::jsonb,3,'Narrowing focuses the research.','original'),
('128.35.c.13.D',3,'Refocusing a research question helps the researcher to:','["find manageable, relevant information", "change the subject entirely", "avoid all sources", "collect more unrelated facts"]'::jsonb,0,'A focused question guides the search.','original'),
('128.35.c.13.E',3,'Which source is most relevant to a report on Texas rivers?','["a recipe blog", "a state water-development report", "a movie review", "a sports score list"]'::jsonb,1,'Relevant sources address the topic.','original'),
('128.35.c.13.E',3,'To find sources quickly in a library database, a student should:','["ask nothing", "guess at titles", "enter specific search terms", "scroll every page"]'::jsonb,2,'Specific terms locate relevant sources.','original'),
('128.35.c.13.F',3,'A student uses two articles and a video to answer one question. This requires:','["a single quotation", "a title page", "only a summary of one", "synthesis of multiple sources"]'::jsonb,3,'The student combines information.','original'),
('128.35.c.13.G.i',4,'A website sells a product and reviews it with only praise. A researcher should suspect:','["bias", "neutrality", "proof", "humor"]'::jsonb,0,'One-sided content signals bias.','original'),
('128.35.c.13.G.i',4,'Which describes a source that omits information?','["It cites every viewpoint", "It ignores facts that conflict with its message", "It gives full context", "It lists all data"]'::jsonb,1,'Omission is a form of bias.','original'),
('128.35.c.13.G.ii',4,'''My cousin got sick at that restaurant, so every meal there is unsafe.'' This is:','["a fair sample", "a quotation", "a hasty generalization", "a valid proof"]'::jsonb,2,'One case cannot prove a rule.','original'),
('128.35.c.13.G.ii',4,'''Either we ban phones or students will fail.'' This faulty reasoning is:','["a rebuttal", "a thesis", "a concession", "either-or"]'::jsonb,3,'It offers only two options when more exist.','original'),
('128.35.c.13.H',3,'Which item belongs in an academic citation?','["the author, title and publication date", "the number of staples", "the reader''s age", "the font used"]'::jsonb,0,'Citations identify the source.','original'),
('128.35.c.13.H',3,'When a student uses someone''s exact sentence, the student must:','["rewrite one word only", "put it in quotation marks and cite the source", "leave out the author", "say nothing"]'::jsonb,1,'Exact words need quotes and credit.','original'),
('128.35.c.13.I',2,'A student uses a spreadsheet to organize survey results. This is:','["a handwritten log", "avoiding data", "incorporating digital technology", "a printed poster"]'::jsonb,2,'Spreadsheets are digital tools.','original'),
('128.35.c.13.I',2,'Which is a sensible use of technology in research?','["using only one app blindly", "ignoring all sources", "copying a website without credit", "using online catalogs to find books"]'::jsonb,3,'Technology should support honest research.','original'),
('128.35.c.13.J',3,'A research report shared as a video with narration and charts uses:','["a multimodal delivery", "a silent delivery", "a handwritten delivery", "an oral-only delivery"]'::jsonb,0,'It combines several modes.','original'),
('128.35.c.13.J',3,'An oral report is best when the audience needs:','["a hidden file", "a spoken explanation with a chance to ask questions", "a printed spreadsheet only", "a silent poster only"]'::jsonb,1,'Oral delivery allows interaction.','original'),
('128.35.c.2.A',3,'Sounding out the unfamiliar word ''cat-er-pil-lar'' by syllables is an example of:','["skipping the word", "memorizing a picture", "applying phonetic knowledge", "guessing from the cover"]'::jsonb,2,'Syllable decoding uses phonics.','original'),
('128.35.c.2.A',3,'Which word has the same vowel sound as ''boat''?','["bought", "boot", "bat", "note"]'::jsonb,3,'Boat and note share the long o sound.','original'),
('128.35.c.2.B',2,'A learner writes answers neatly so that:','["a reader can understand every word", "the teacher skips them", "mistakes are hidden", "the page looks longer"]'::jsonb,0,'Legible writing communicates.','original'),
('128.35.c.2.B',2,'Which is a complete thought?','["Because the lab", "The class finished the lab.", "Finished the", "After the long lab"]'::jsonb,1,'A complete thought has a subject and a verb.','original'),
('128.35.c.3.A',3,'To find the meaning of ''photosynthesis'' in a science text, a learner can use:','["a poster title", "a map", "a glossary", "a timeline"]'::jsonb,2,'Glossaries define key terms.','original'),
('128.35.c.3.A',3,'A digital dictionary can help a learner by:','["hiding the definition", "erasing the word", "writing the essay", "showing meanings, pronunciations and examples"]'::jsonb,3,'Digital resources clarify words.','original'),
('128.35.c.3.B',4,'''The senator''s speech was a bridge between the two parties.'' The word bridge here is:','["figurative", "a verb of motion", "a place name", "literal"]'::jsonb,0,'It does not mean a real structure.','original'),
('128.35.c.3.B',4,'The word ''cheap'' has a negative connotation, while ''affordable'' has a:','["negative denotation", "positive connotation", "spelling rule", "scientific meaning"]'::jsonb,1,'Connotation carries feelings.','original'),
('128.35.c.3.C',3,'The French phrase ''deja vu'' used in English means:','["a new beginning", "a farewell", "a feeling of having already experienced something", "a recipe"]'::jsonb,2,'Deja vu means already seen.','original'),
('128.35.c.3.C',3,'The phrase ''status quo'' refers to:','["a future plan", "a missing item", "a rare event", "the existing state of affairs"]'::jsonb,3,'Status quo is the current situation.','original'),
('128.35.c.3.D',2,'Which word names an action in a science lab?','["measure", "yesterday", "beside", "green"]'::jsonb,0,'Measure is a verb.','original'),
('128.35.c.3.D',2,'Which phrase names a location?','["a loud noise", "across the hall", "very quickly", "last week"]'::jsonb,1,'Across the hall tells where.','original'),
('128.35.c.3.E',3,'The word ''lead'' can mean a metal or to guide. This is a:','["suffix", "prefix", "multiple-meaning word", "contraction"]'::jsonb,2,'One spelling, several meanings.','original'),
('128.35.c.3.F',3,'The idiom ''under the weather'' means:','["hiding outdoors", "predicting storms", "standing in rain", "feeling slightly ill"]'::jsonb,3,'Idioms are figurative.','original'),
('128.35.c.4',2,'A learner reads an article, discusses it and writes a response. This shows that language skills:','["work together and build one another", "stop at speaking", "develop apart", "never overlap"]'::jsonb,0,'Listening, speaking, reading and writing are connected.','original'),
('128.35.c.4',2,'Practicing speaking with a partner also helps a learner''s:','["bus schedule", "listening and vocabulary", "map reading", "art supplies"]'::jsonb,1,'Skills strengthen each other.','original'),
('128.35.c.5',2,'A student listens to a lecture, then writes notes and explains them to a partner. This combines:','["only drawing", "only counting", "listening, writing and speaking", "only silence"]'::jsonb,2,'Several language skills are integrated.','original'),
('128.35.c.5',2,'Which task integrates reading and writing?','["Looking out a window", "Sitting quietly", "Counting desks", "Reading a story and writing a summary"]'::jsonb,3,'Both skills are used together.','original'),
('128.35.c.6.A',3,'A student reads a recipe to bake bread. The purpose is to:','["get steps and amounts for cooking", "find a rhyme", "learn a poem", "study a legend"]'::jsonb,0,'Purpose guides how a text is read.','original'),
('128.35.c.6.A',3,'Reading an assigned chapter for a quiz sets the purpose of:','["avoiding the text", "learning information to be tested", "finding a rhyme", "naming the author"]'::jsonb,1,'Assigned reading has an academic purpose.','original'),
('128.35.c.6.B',3,'During reading, a learner asks ''Why did the character do that?'' The question:','["ends the story", "changes the author", "builds understanding while reading", "removes details"]'::jsonb,2,'Questions deepen comprehension.','original'),
('128.35.c.6.B',3,'Asking questions after reading helps a learner to:','["skip the plot", "close the book permanently", "forget details", "review and deepen understanding"]'::jsonb,3,'Post-reading questions reinforce meaning.','original'),
('128.35.c.6.C',3,'A learner sees a title with a rocket and predicts a space story. The prediction came from:','["the title and picture", "the author''s age", "page count", "the paper''s color"]'::jsonb,0,'Text features support predictions.','original'),
('128.35.c.6.C',3,'A prediction is corrected when:','["the font changes", "the text shows something different", "a new page begins", "the learner stops reading"]'::jsonb,1,'Evidence changes a prediction.','original'),
('128.35.c.6.D',3,'While reading ''steam rising from the soup'', a reader can picture:','["a night sky", "a dry desert", "warm food on a table", "a frozen lake"]'::jsonb,2,'Sensory details create mental images.','original'),
('128.35.c.6.D',3,'Visualizing helps most with:','["copyright pages", "page numbers", "tables of contents", "descriptive passages"]'::jsonb,3,'Description invites mental images.','original'),
('128.35.c.6.E',3,'A student compares a character''s fear to a time she moved to a new town. This is a connection to:','["personal experience", "glossary entries", "the index", "punctuation"]'::jsonb,0,'Text-to-self connection.','original'),
