('128.35.c.9.D.iv',4,'If an essay compares two cultures, which design fits its thesis?','["alphabetical sentences", "organizing by similarities and then differences", "one long list", "random paragraphs"]'::jsonb,1,'Organization should support the thesis.','original'),
('128.35.c.9.D.iv',4,'The relationship between organizational design and thesis means:','["the thesis is hidden", "structure is unimportant", "the structure should support the main point", "only the title matters"]'::jsonb,2,'Design serves the thesis.','original'),
('128.35.c.9.E.i',3,'A convincing conclusion in an argument:','["adds an unrelated topic", "repeats the introduction exactly", "apologizes", "restates the claim and leaves the reader with a final appeal"]'::jsonb,3,'Strong conclusions reinforce the claim.','original'),
